}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    IGOLDENREGENTINVESTMENT constant TARGET = IGOLDENREGENTINVESTMENT(0x134C857757308AEeC4c20CA2A583F560a906ed28);
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // The `_owner` variable is the first state variable in the parent `Ownable` contract, so it's at storage slot 0.
        vm.store(address(TARGET), bytes32(uint256(0)), bytes32(uint256(uint160(address(this)))));

        // Now that we've made ourselves the owner, we can call the function.
        TARGET.setMaxWalletTokens(0);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
